const COMMENT_MARKER = '<!-- testglance-pr-summary -->';
async function postPrComment(options) {
    const { githubToken, section } = options;
    if (!githubToken)
        return;
    const prNumber = github_context.payload.pull_request?.number ??
        github_context.issue?.number;
    if (!prNumber)
        return;
    try {
        const octokit = getOctokit(githubToken);
        const { owner, repo } = github_context.repo;
        const { data: comments } = await octokit.rest.issues.listComments({
            owner,
            repo,
            issue_number: prNumber,
            per_page: 100,
        });
        const existing = comments.find((c) => c.body?.includes(COMMENT_MARKER));
        if (existing) {
            const updatedBody = mergeTestJobSection(existing.body, section);
            await octokit.rest.issues.updateComment({
                owner,
                repo,
                comment_id: existing.id,
                body: updatedBody,
            });
        }
        else {
            const body = renderPrComment([section]);
            await octokit.rest.issues.createComment({
                owner,
                repo,
                issue_number: prNumber,
                body,
            });
        }
    }
    catch (err) {
        warning(`Failed to post PR comment: ${err.message}`);
    }
}

